        PlanChange: {
            /**
             * @description The host path.
             * @example /etc/care-pi/rendered/care/backend.env
             */
            path: string;
            /**
             * @description The kind of change.
             * @enum {string}
             */
            kind: "add" | "modify" | "delete";
        };
        /**
         * @description The action kinds of `agent/internal/plan`, in execution order. A later version can add kinds.
         * @example restart
         * @enum {string}
         */
        PlanActionKind: "ensure-dirs" | "set-secrets" | "write-files" | "delete-files" | "daemon-reload" | "enable-target" | "pull-images" | "full-cycle" | "start-target" | "restart" | "reload-caddy" | "ensure-buckets" | "ensure-stanza" | "ensure-fe" | "write-lock";
