        ApplyRequest: {
            /**
             * @description A text for the job journal (`--reason`).
             * @example preset change
             */
            reason?: string | null;
            /**
             * @description Resolve the tracked refs again (`--update`).
             * @default false
             */
            update: boolean;
        };
