            error: components["schemas"]["Problem"] | null;
            /** @description The result of a job that succeeded. `null` for the other states, and for kinds without a result. */
            result: components["schemas"]["JobResult"] | null;
            /** @description The id of the last event of the job. `0` before the first event. */
            last_event_id: number;
